// src/frontdoor/title-fonts.ts
//
// The lettering a business chooses for its name and its menu's section
// titles: four faces, each for a different kind of place, so no two menus
// need look alike. Latin letters only, one weight each (10-23 KB), all under
// the SIL Open Font License 1.1 (fonts/*-OFL.txt):
//   classic  Playfair Display 700, by the Playfair Display Project Authors (PlayfairDisplay-OFL.txt)
//   roman    Cinzel 600, by the Cinzel Project Authors (Cinzel-OFL.txt)
//   elegant  Cormorant Garamond 600, by the Cormorant Project Authors (CormorantGaramond-OFL.txt)
//   modern   Jost 600, by the Jost Project Authors (Jost-OFL.txt)
//
// Kept here so they ship with the service, served at /c-assets/title-<key>.woff2
// (the page loads fonts only from its own address). A page downloads only the
// one its business chose.

export type TitleFont = "classic" | "roman" | "elegant" | "modern";

export const TITLE_FONT_KEYS: TitleFont[] = ["classic", "roman", "elegant", "modern"];

type Face = { family: string; weight: number; version: string; file: Buffer };

const face = (family: string, weight: number, version: string, lines: string[]): Face => ({ family, weight, version, file: Buffer.from(lines.join(""), "base64") });

